def _risk_snapshot_number(value: Any, default: float = 0.0) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return float(default)
    if pd.isna(number):
        return float(default)
    return number


def _clean_risk_book_snapshot(raw: Any) -> dict[str, Any]:
    """Validate the browser-backed last-known E*TRADE Risk Book snapshot."""
    if not isinstance(raw, dict):
        raw = {}

    try:
        revision = max(0, int(raw.get("revision", 0) or 0))
    except (TypeError, ValueError):
        revision = 0

    rows: list[dict[str, Any]] = []
    for source in raw.get("rows", []) or []:
        if not isinstance(source, dict):
            continue
        row = {
            "Symbol": str(source.get("Symbol") or "").strip().upper(),
            "Type": str(source.get("Type") or "").strip(),
            "CUSIP": str(source.get("CUSIP") or "").strip(),
            "Market Value": _risk_snapshot_number(source.get("Market Value"), 0.0),
            "Gain/Loss": _risk_snapshot_number(source.get("Gain/Loss"), 0.0),
            "Gain/Loss %": _risk_snapshot_number(source.get("Gain/Loss %"), 0.0),
        }
        if row["Symbol"] or row["CUSIP"]:
            rows.append(row)

    settings: dict[str, Any] = {}
    source_settings = raw.get("settings") if isinstance(raw.get("settings"), dict) else {}
    for key in _RISK_BOOK_NUMERIC_SETTINGS:
        if key in source_settings:
            settings[key] = _risk_snapshot_number(source_settings.get(key), 0.0)
    for key in _RISK_BOOK_TEXT_SETTINGS:
        if key in source_settings:
            settings[key] = str(source_settings.get(key) or "").strip()

    return {
        "revision": revision,
        "saved_at": _risk_snapshot_number(raw.get("saved_at"), 0.0),
        "portfolio_saved_at": _risk_snapshot_number(raw.get("portfolio_saved_at"), 0.0),
        "account_key": str(raw.get("account_key") or "").strip(),
        "account_name": str(raw.get("account_name") or "").strip(),
        "account_total": _risk_snapshot_number(raw.get("account_total"), 0.0),
        "cash_available": _risk_snapshot_number(raw.get("cash_available"), 0.0),
        "rows": rows,
        "settings": settings,
    }


def _load_persisted_risk_book_snapshot() -> dict[str, Any] | None:
    """Load the last Risk Book from this browser across sessions/redeploys."""
    session_value = _clean_risk_book_snapshot(
        st.session_state.get(_RISK_BOOK_SNAPSHOT_SESSION_KEY)
    )
    if session_value["rows"]:
        return session_value

    browser = _risk_book_state_component(
        storage_key=_RISK_BOOK_STORAGE_KEY,
        server_state=session_value,
        key="raj_risk_book_state_reader_v1",
        default=None,
    )
    if isinstance(browser, dict) and isinstance(browser.get("state"), dict):
        browser_state = _clean_risk_book_snapshot(browser["state"])
        if browser_state["rows"] and (
            browser_state["revision"] > session_value["revision"]
            or not session_value["rows"]
        ):
            session_value = browser_state

    if not session_value["rows"]:
        return None

    st.session_state[_RISK_BOOK_SNAPSHOT_SESSION_KEY] = session_value
    return session_value


def _restore_risk_book_settings(snapshot: dict[str, Any] | None) -> None:
    """Restore prior Risk controls only when this Streamlit session has no value."""
    if not snapshot:
        return
    settings = snapshot.get("settings") if isinstance(snapshot.get("settings"), dict) else {}
    for key in (*_RISK_BOOK_NUMERIC_SETTINGS, *_RISK_BOOK_TEXT_SETTINGS):
        if key not in st.session_state and key in settings:
            st.session_state[key] = settings[key]


def _risk_book_snapshot_frame(snapshot: dict[str, Any] | None) -> pd.DataFrame:
    if not snapshot:
        return pd.DataFrame()
    rows = snapshot.get("rows") or []
    if not isinstance(rows, list):
        return pd.DataFrame()
    return pd.DataFrame(rows)


def _risk_book_snapshot_settings() -> dict[str, Any]:
    values: dict[str, Any] = {}
    for key in _RISK_BOOK_NUMERIC_SETTINGS:
        if key in st.session_state:
            values[key] = _risk_snapshot_number(st.session_state.get(key), 0.0)
    for key in _RISK_BOOK_TEXT_SETTINGS:
        if key in st.session_state:
            values[key] = str(st.session_state.get(key) or "").strip()
    return values


def _risk_book_portfolio_saved_at(client: Any, account_key: str) -> float:
    """Preserve the source snapshot time when the shared E*TRADE cache exposes it."""
    cache_age = getattr(client, "cache_age", None)
    if callable(cache_age):
        try:
            age = cache_age("portfolio", str(account_key))
            if age is not None:
                return max(0.0, time.time() - float(age))
        except Exception:
            pass
    return time.time()


def _persist_risk_book_snapshot(
    *,
    account_key: str,
    account_name: str,
    normalized: pd.DataFrame,
    account_total: float,
    cash_available: float,
    portfolio_saved_at: float,
) -> dict[str, Any]:
    """Persist only the Risk fields needed to rebuild the last session locally."""
    rows: list[dict[str, Any]] = []
    if isinstance(normalized, pd.DataFrame) and not normalized.empty:
        for _, source in normalized.iterrows():
            row = {
                "Symbol": str(source.get("Symbol") or "").strip().upper(),
                "Type": str(source.get("Type") or "").strip(),
                "CUSIP": str(source.get("CUSIP") or "").strip(),
                "Market Value": _risk_snapshot_number(source.get("Market Value"), 0.0),
                "Gain/Loss": _risk_snapshot_number(source.get("Gain/Loss"), 0.0),
                "Gain/Loss %": _risk_snapshot_number(source.get("Gain/Loss %"), 0.0),
            }
            if row["Symbol"] or row["CUSIP"]:
                rows.append(row)

    existing = _clean_risk_book_snapshot(
        st.session_state.get(_RISK_BOOK_SNAPSHOT_SESSION_KEY)
    )
    candidate = {
        "account_key": str(account_key or "").strip(),
        "account_name": str(account_name or "").strip(),
        "account_total": _risk_snapshot_number(account_total, 0.0),
        "cash_available": _risk_snapshot_number(cash_available, 0.0),
        "portfolio_saved_at": _risk_snapshot_number(portfolio_saved_at, time.time()),
        "rows": rows,
        "settings": _risk_book_snapshot_settings(),
    }
    same_payload = all(
        existing.get(key) == candidate.get(key)
        for key in (
            "account_key",
            "account_name",
            "account_total",
            "cash_available",
            "portfolio_saved_at",
            "rows",
            "settings",
        )
    )
    if same_payload:
        state = existing
    else:
        state = {
            **candidate,
            "revision": existing["revision"] + 1,
            "saved_at": time.time(),
        }
        st.session_state[_RISK_BOOK_SNAPSHOT_SESSION_KEY] = state

    _risk_book_state_component(
        storage_key=_RISK_BOOK_STORAGE_KEY,
        server_state=state,
        key="raj_risk_book_state_writer_v1",
        default=None,
    )
    return state


def _risk_book_memory_age_text(saved_at: float) -> str:
    seconds = max(0, int(time.time() - float(saved_at or 0.0)))
    if seconds < 60:
        return f"{seconds}s ago"
    if seconds < 3600:
        return f"{seconds // 60}m ago"
    if seconds < 86400:
        return f"{seconds // 3600}h {(seconds % 3600) // 60}m ago"
    return f"{seconds // 86400}d {(seconds % 86400) // 3600}h ago"


@st.cache_resource
def _risk_intent_vault() -> dict[str, dict[str, Any]]:
    """Process-local fallback for LONG-TERM intent across page refreshes."""
    return {}


def _normalize_intent_symbol(value: Any) -> str:
    return str(value or "").strip().upper()


def _risk_intent_account_token(account_key: str) -> str:
    """Hash the broker account key before using it in browser-storage keys."""
    raw = str(account_key or "default").encode("utf-8")
    return hashlib.sha256(raw).hexdigest()[:24]


def _risk_intent_session_key(account_key: str) -> str:
    return "_risk_intent_state::" + _risk_intent_account_token(account_key)


def _risk_intent_storage_key(account_key: str) -> str:
    return "raj-terminal-risk-intent-v1:" + _risk_intent_account_token(account_key)


def _clean_risk_intent_state(raw: Any) -> dict[str, Any]:
    """Return the tiny persisted schema: revision + checked ticker symbols."""
    revision = 0
    tickers: list[str] = []
    if isinstance(raw, dict):
        try:
            revision = max(0, int(raw.get("revision", 0) or 0))
        except (TypeError, ValueError):
            revision = 0
        for value in raw.get("tickers", []) or []:
            ticker = _normalize_intent_symbol(value)
            if ticker and ticker not in tickers:
                tickers.append(ticker)
    return {"revision": revision, "tickers": tickers[:500]}


def _account_intent_overrides(account_key: str) -> dict[str, str]:
    """Return account-scoped one-off holding-intent overrides for this session."""
    all_overrides = st.session_state.setdefault("risk_sleeve_intent_overrides", {})
    if not isinstance(all_overrides, dict):
        all_overrides = {}
        st.session_state["risk_sleeve_intent_overrides"] = all_overrides

    key = str(account_key or "default")
    account_overrides = all_overrides.get(key)
    if not isinstance(account_overrides, dict):
        account_overrides = {}
        all_overrides[key] = account_overrides
    return account_overrides


def _store_risk_intent_state(
    account_key: str,
    state: dict[str, Any],
) -> dict[str, Any]:
    cleaned = _clean_risk_intent_state(state)
    st.session_state[_risk_intent_session_key(account_key)] = cleaned
    _risk_intent_vault()[_risk_intent_storage_key(account_key)] = dict(cleaned)
    return cleaned


def _current_risk_intent_state(account_key: str) -> dict[str, Any]:
    session_state = st.session_state.get(_risk_intent_session_key(account_key))
    if isinstance(session_state, dict):
        return _clean_risk_intent_state(session_state)

    vault_state = _risk_intent_vault().get(_risk_intent_storage_key(account_key))
    if isinstance(vault_state, dict):
        return _store_risk_intent_state(account_key, vault_state)

    # Seamlessly migrate any LONG-TERM choices already made in this live
    # session before browser persistence existed.
    account_overrides = _account_intent_overrides(account_key)
    tickers = sorted(
        ticker
        for ticker, intent in account_overrides.items()
        if _normalize_intent_symbol(intent) == RISK_INTENT_LONG_TERM
        and _normalize_intent_symbol(ticker)
    )
    return _store_risk_intent_state(
        account_key,
        {"revision": 0, "tickers": tickers},
    )


def _reconcile_risk_intent_state(
    state: dict[str, Any],
    active_symbols: list[str],
) -> tuple[dict[str, Any], bool]:
    """Drop saved LONG-TERM tickers only after they disappear from holdings."""
    cleaned = _clean_risk_intent_state(state)
    active = {
        _normalize_intent_symbol(symbol)
        for symbol in active_symbols
        if _normalize_intent_symbol(symbol)
    }
    kept = [ticker for ticker in cleaned["tickers"] if ticker in active]
    changed = kept != cleaned["tickers"]
    if changed:
        cleaned["revision"] += 1
        cleaned["tickers"] = kept
    return cleaned, changed


def _hydrate_account_overrides(
    account_key: str,
    state: dict[str, Any],
) -> dict[str, str]:
    account_overrides = _account_intent_overrides(account_key)
    saved = set(_clean_risk_intent_state(state)["tickers"])

    for ticker in list(account_overrides):
        if (
            _normalize_intent_symbol(account_overrides.get(ticker))
            == RISK_INTENT_LONG_TERM
            and _normalize_intent_symbol(ticker) not in saved
        ):
            account_overrides.pop(ticker, None)

    for ticker in saved:
        account_overrides[ticker] = RISK_INTENT_LONG_TERM
    return account_overrides


def _load_persisted_intent_overrides(
    account_key: str,
    active_symbols: list[str],
) -> tuple[dict[str, str], dict[str, Any]]:
    """Load browser-backed LONG-TERM choices and prune sold positions."""
    state = _current_risk_intent_state(account_key)
    browser = _risk_intent_state_component(
        storage_key=_risk_intent_storage_key(account_key),
        server_state=state,
        key="raj_risk_intent_state_reader_" + _risk_intent_account_token(account_key),
        default=None,
    )
    if isinstance(browser, dict) and isinstance(browser.get("state"), dict):
        browser_state = _clean_risk_intent_state(browser["state"])
        if browser_state["revision"] > state["revision"] or (
            state["revision"] == 0
            and not state["tickers"]
            and browser_state["tickers"]
        ):
            state = browser_state

    state, _ = _reconcile_risk_intent_state(state, active_symbols)
    state = _store_risk_intent_state(account_key, state)
    return _hydrate_account_overrides(account_key, state), state


def _sync_risk_intent_browser(
    account_key: str,
    state: dict[str, Any],
) -> None:
    """Write checked tickers to this browser without exposing brokerage data."""
    _risk_intent_state_component(
        storage_key=_risk_intent_storage_key(account_key),
        server_state=_clean_risk_intent_state(state),
        key="raj_risk_intent_state_writer_" + _risk_intent_account_token(account_key),
        default=None,
    )


def _save_risk_intent_overrides(
    account_key: str,
    account_overrides: dict[str, str],
) -> dict[str, Any]:
    state = _current_risk_intent_state(account_key)
    tickers = sorted(
        {
            _normalize_intent_symbol(ticker)
            for ticker, intent in account_overrides.items()
            if _normalize_intent_symbol(intent) == RISK_INTENT_LONG_TERM
            and _normalize_intent_symbol(ticker)
        }
    )
    state["revision"] += 1
    state["tickers"] = tickers
    return _store_risk_intent_state(account_key, state)


def _apply_intent_overrides(
    classified: pd.DataFrame,
    account_overrides: dict[str, str],
) -> pd.DataFrame:
    """Promote selected one-off tickers to LONG-TERM without changing base rules."""
    result = classified.copy()
    if "Symbol" not in result.columns:
        result["Symbol"] = ""

    symbols = result["Symbol"].astype(str).str.strip().str.upper()
    result["Intent"] = [
        (
            RISK_INTENT_LONG_TERM
            if str(account_overrides.get(symbol) or "").upper() == RISK_INTENT_LONG_TERM
            else RISK_INTENT_AUTO
        )
        for symbol in symbols
    ]

    manual_mask = result["Intent"].eq(RISK_INTENT_LONG_TERM)
    result.loc[manual_mask, "Sleeve"] = "LONG-TERM"
    if "Sleeve Rule" not in result.columns:
        result["Sleeve Rule"] = ""
    result.loc[manual_mask, "Sleeve Rule"] = "MANUAL LONG-TERM INTENT"
    return result


def _risk_override_widget_key(account_key: str, symbol: str, row_uid: str) -> str:
    """Return a row-unique widget key while keeping intent ticker-level."""
    return (
        "risk_long_term_override::"
        + str(account_key or "default")
        + "::"
        + str(row_uid)
        + "::"
        + str(symbol or "").strip().upper()
    )


def _set_long_term_override(
    account_key: str,
    symbol: str,
    widget_key: str,
) -> None:
    """Apply one ticker-level LONG-TERM override from a native checkbox."""
    normalized_symbol = str(symbol or "").strip().upper()
    if not normalized_symbol:
        return

    account_overrides = _account_intent_overrides(account_key)
    wants_long_term = bool(st.session_state.get(widget_key, False))
    if wants_long_term:
        account_overrides[normalized_symbol] = RISK_INTENT_LONG_TERM
    else:
        account_overrides.pop(normalized_symbol, None)
    _save_risk_intent_overrides(account_key, account_overrides)


